      frameRate: frameRate ?? context?.frameRate ?? settings.performance?.frameRate,
      onPaint: () => {manager.current?.refresh();if(adaptiveBackdrop)setBackdropKind(classifyGlassBackdrop(scene,element));},
    });
    mirror.current = subscription;
    setSceneReady(true);
    return () => {
