        radius: Math.min(safeRadius, size.w / 2, size.h / 2),
        splay: p.splay,
        feather: p.feather,
        curve: p.curve,
        pad: samplingPad,
        optics: optical,
        shape,
        deformation: pullX === undefined && pullY === undefined ? undefined : {x: pullX ?? 0, y: pullY ?? 0},
