export function attachSceneMirror(
  root: HTMLElement,
  host: HTMLElement,
  surface: HTMLElement,
  pad: number,
  options: SceneMirrorOptions,
): SceneMirror {
  let record = records.get(root);
  if (!record) {
    const coarse =
      typeof matchMedia === "function" &&
      matchMedia("(pointer: coarse)").matches;
    const requested = options.frameRate;
    const frameRate =
      typeof requested === "number" && Number.isFinite(requested)
        ? Math.max(1, Math.min(60, requested))
        : coarse
          ? 30
          : 60;
    record = new SceneRecord(root, frameRate);
    records.set(root, record);
  }
  const geometryElements: HTMLElement[] = [];
  for (
    let element: HTMLElement | null = surface;
    element;
    element = element.parentElement
  )
    geometryElements.push(element);
  const sink: Sink = {
    host,
    surface,
    pad,
    visible: true,
    pairs: [],
    prefix: `glass-mirror-${++nextMirror}`,
    layered: false,
    geometryKey: "",
    ids: new Map(),
    geometryElements,
    onPaint: options.onPaint,
  };
  record.sinks.add(sink);
  record.rebuild = true;
  record.geometry = true;
  record.flush();
  const observer =
    typeof IntersectionObserver !== "undefined"
      ? new IntersectionObserver(([entry]) => {
          sink.visible = entry.isIntersecting;
          if (sink.visible) {
            record!.rebuild = true;
            record!.geometry = true;
            record!.schedule();
          } else if (!record!.visible) record!.cancel();
        })
      : null;
  observer?.observe(surface);
  // Portaled dialogs and gesture-driven drawers can move without a React
  // render. Track their own style changes and active ancestor transitions.
  const geometryObserver = new MutationObserver(() => {
    record!.geometry = true;
    record!.schedule();
  });
  const wakeGeometry = (event: Event) => {
    if (
      !(event.target instanceof HTMLElement) ||
      !geometryElements.includes(event.target)
    )
      return;
    record!.geometry = true;
    record!.schedule();
  };
  for (const element of geometryElements) {
    geometryObserver.observe(element, {
      attributes: true,
      attributeFilter: ["style", "class", "data-state"],
    });
    element.addEventListener("transitionrun", wakeGeometry);
    element.addEventListener("animationstart", wakeGeometry);
  }
  record.schedule();
  let disposed = false;
  return {
    setVisible(value) {
      if (disposed) return;
      sink.visible = value;
      if (value) {
        record!.rebuild = true;
        record!.schedule();
      } else if (!record!.visible) record!.cancel();
    },
    updateGeometry() {
      if (disposed) return;
      if (sink.geometryKey === record!.geometryKey(sink)) return;
      record!.geometry = true;
      record!.flush();
    },
    destroy() {
      if (disposed) return;
      disposed = true;
      geometryObserver.disconnect();
      for (const element of geometryElements) {
        element.removeEventListener("transitionrun", wakeGeometry);
        element.removeEventListener("animationstart", wakeGeometry);
      }
      observer?.disconnect();
      record!.sinks.delete(sink);
      host.replaceChildren();
      if (!record!.sinks.size) {
        record!.destroy();
        records.delete(root);
      }
    },
  };
}

/** Call after imperative/WAAPI/canvas changes. Immediate mode mirrors a JS-driven
 * animation before the browser paints that frame, avoiding a frame of lag.
 */
export function invalidateGlassScene(
  root: HTMLElement | null,
  options: { target?: Element; immediate?: boolean } = {},
) {
  if (!root) return;
  const record = records.get(root);
  if (!record) return;
  if (options.target) record.dirty.add(options.target);
  else record.rebuild = true;
  record.findAnimations();
  if (
    options.immediate &&
    performance.now() - record.last + 0.5 >= 1000 / record.frameRate
  ) {
    record.markMutations(record.observer.takeRecords());
    for (const target of record.animated) record.dirty.add(target);
    for (const target of record.media) record.dirty.add(target);
    record.cancel();
    record.last = performance.now();
    record.flush();
    if (record.animated.size || record.media.length) record.schedule();
  } else record.schedule();
}

/** A document-wide budget. Controls that share a panel do not register lenses. */
interface LensEntry {
  element: HTMLElement;
  visible: boolean;
  active: boolean | null;
  limit: number;
  priority: number;
  onChange: (active: boolean) => void;
}

const entries = new Set<LensEntry>();
let observer: IntersectionObserver | null = null;
let listening = false;

const deviceLimit = () =>
  typeof matchMedia === "function" && matchMedia("(pointer: coarse)").matches
    ? 3
    : 5;
const boundedLimit = (limit?: number) =>
  Math.max(
    1,
    Math.min(deviceLimit(), Number.isFinite(limit) ? Math.floor(limit!) : deviceLimit()),
  );

function reconcile() {
  const visible = [...entries].filter((entry) => entry.visible);
  const limit = Math.min(deviceLimit(), ...visible.map((entry) => entry.limit));
  const selected = new Set(
    document.hidden
      ? []
      : visible.sort((a, b) => b.priority - a.priority).slice(0, limit),
  );
  for (const entry of entries) {
    const active = selected.has(entry);
    if (active === entry.active) continue;
    entry.active = active;
    entry.onChange(active);
  }
}

export function registerGlassLens(
  element: HTMLElement,
  onChange: LensEntry["onChange"],
  options: { limit?: number; priority?: number } = {},
) {
  const rect = element.getBoundingClientRect();
  const entry: LensEntry = {
    element,
    onChange,
    limit: boundedLimit(options.limit),
    priority: options.priority ?? 0,
    // Publish even an initial false state when a component re-registers.
    active: null,
    visible:
      rect.width > 0 && rect.height > 0 && rect.bottom > 0 && rect.right > 0 &&
      rect.top < innerHeight && rect.left < innerWidth,
  };
  entries.add(entry);
  if (!listening) {
    document.addEventListener("visibilitychange", reconcile);
    listening = true;
  }
  if (!observer && typeof IntersectionObserver !== "undefined") {
    observer = new IntersectionObserver((changes) => {
      for (const change of changes) {
        for (const candidate of entries) {
          if (candidate.element === change.target) {
            candidate.visible = change.isIntersecting;
          }
        }
      }
      reconcile();
    });
  }
  observer?.observe(element);
  reconcile();

  let disposed = false;
  return () => {
    if (disposed) return;
    disposed = true;
    entries.delete(entry);
    observer?.unobserve(element);
    reconcile();
    if (!entries.size) {
      observer?.disconnect();
      observer = null;
      document.removeEventListener("visibilitychange", reconcile);
      listening = false;
    }
  };
}

/** Diagnostics for tests and tooling; never starts a polling loop. */
export function getGlassBudgetSnapshot() {
  return {
    registered: entries.size,
    visible: [...entries].filter((entry) => entry.visible).length,
    active: [...entries].filter((entry) => entry.active).length,
    deviceLimit: deviceLimit(),
  };
}

