    filter.append(element("feColorMatrix", {in: "ambient", type: "saturate", values: 1.5, result: "ambientColor"}));
    const energy = element("feComponentTransfer", {in: "ambientColor", result: "ambientLight"});
    for (const channel of ["feFuncR", "feFuncG", "feFuncB"] as const) energy.append(element(channel, {type: "linear", slope: 1.15}));
    filter.append(energy);
    const light = element("feImage", {href: rimMap, x: 0, y: 0, width: config.width, height: config.height, preserveAspectRatio: "none", result: "rimLight"});
    light.setAttributeNS("http://www.w3.org/1999/xlink", "xlink:href", rimMap);
    filter.append(light);
    const columnScale = Math.max(0, Math.min(8192, Number.isFinite(config.rimScale) ? config.rimScale! : 0));
    if (columnScale > 0) {
      const coordinates = element("feComponentTransfer", {in:"rimLight",result:"columnCoordinates"});
      coordinates.append(element("feFuncR", {type:"linear",slope:255/254,intercept:-1/254}),element("feFuncG", {type:"linear",slope:255/254,intercept:-1/254}));
      filter.append(coordinates,element("feDisplacementMap",{in:"ambientLight",in2:"columnCoordinates",scale:columnScale,xChannelSelector:"R",yChannelSelector:"G",result:"columnColor"}));
    }
    filter.append(element("feComposite", {in: columnScale > 0 ? "columnColor" : "ambientLight", in2: "rimLight", operator: "in", result: "maskedColor"}));
    const opacity = element("feComponentTransfer", {in: "maskedColor", result: "coloredRim"});
    // A thin colored edge needs enough energy to survive the neutral tint and
    // white specular layer above it. Keep its coverage soft, rather than wider.
    opacity.append(element("feFuncA", {type: "linear", slope: bleed * Math.min(1, 2 * (config.glint ?? 1))}));
    filter.append(opacity);
    // Normal composition retains colored glints on white backdrops as well.
    filter.append(element("feBlend", {in: "coloredRim", in2: transmitted, mode: "normal"}));
  }
  return filter;
}

/** New ID and node per *paint*, not per map. Retain the previous definition
 * for one handoff and cap the housing at two filters; no unbounded SVG growth.
 */
export class GlassFilterManager {
  template: SVGFilterElement | null = null;
  key = "";
  refreshes = 0;
  suffix = "";
  constructor(private housing: SVGSVGElement, private target: HTMLElement, private property: "filter" | "backdropFilter" = "filter") {}
  update(config: GlassFilterConfig) {
    this.suffix = config.postFilter ? ` ${config.postFilter}` : "";
    const key = JSON.stringify(config);
    if (this.key !== key) { this.template = buildDisplacementFilter(config); this.key = key; }
    this.refresh();
  }
  refresh = () => {
    if (!this.template) return;
    const filter = this.template.cloneNode(true) as SVGFilterElement;
    const id = `liquid-frame-${++filterSequence}`;
    filter.id = id;
    this.housing.appendChild(filter);
    this.target.style[this.property] = `url("#${id}")${this.suffix}`;
    if (this.property === "backdropFilter") this.target.style.setProperty("-webkit-backdrop-filter", `url("#${id}")${this.suffix}`);
    while (this.housing.children.length > 2) this.housing.firstElementChild!.remove();
    this.refreshes++;
    this.target.dataset.glassFilterPaints = String(this.refreshes);
  };
  destroy() {
    this.target.style[this.property] = "";
    if (this.property === "backdropFilter") this.target.style.removeProperty("-webkit-backdrop-filter");
    this.housing.replaceChildren();
    this.template = null;
  }
}

"use client";

import {
  createContext,
  useContext,
  useMemo,
  useRef,
  useState,
  type HTMLAttributes,
  type ReactNode,
  type RefObject,
} from "react";
import type { LensParams, GlassOptics, GlassPreset } from "@/lib/glass";

export type GlassThemeBehavior = "unitheme" | "duotheme";

export interface GlassSettings {
  surface?: GlassPreset;
  /** Keeps finish and blur unchanged; switches only optical bending on/off. */
  refraction?: boolean;
  /** Diagnostic contour from the same geometry as the refracting mask. */
  showOutlines?: boolean;
  /** Unitheme adapts ink; duotheme keeps the supplied ink while material changes. */
  themeBehavior?: GlassThemeBehavior;
  config?: Partial<LensParams>;
  optics?: Partial<GlassOptics>;
  radius?: number;
  ink?: "auto" | "light" | "dark";
  contrastProtection?: boolean;
  performance?: { maxActiveSurfaces?: number; frameRate?: number };
}
const GlassSettingsContext = createContext<GlassSettings>({});
export function useGlassSettings() {
  return useContext(GlassSettingsContext);
}
/** Shared optical settings for components and portals, without another DOM layer. */
export function GlassSettingsProvider({
  children,
  surface,
  config,
  optics,
  radius,
  ink,
  contrastProtection,
  performance,
  themeBehavior,
  refraction,
  showOutlines,
}: GlassSettings & { children: ReactNode }) {
  const parent = useGlassSettings();
  const [initialInk] = useState<"light" | "dark">(ink === "light" ? "light" : "dark");
  const behavior = themeBehavior ?? parent.themeBehavior ?? "unitheme";
  const selectedInk = ink ?? parent.ink;
  const resolvedInk = behavior === "duotheme" && (!selectedInk || selectedInk === "auto") ? initialInk : selectedInk;
  const value = useMemo(
    () => ({
      surface: surface ?? parent.surface,
      config: { ...parent.config, ...config },
      optics: { ...parent.optics, ...optics },
      radius: radius ?? parent.radius,
      ink: resolvedInk,
      themeBehavior: behavior,
      contrastProtection: contrastProtection ?? parent.contrastProtection,
      performance: { ...parent.performance, ...performance },
      refraction: refraction ?? parent.refraction ?? true,
      showOutlines: showOutlines ?? parent.showOutlines ?? false,
    }),
    [parent, surface, config, optics, radius, resolvedInk, behavior, contrastProtection, performance, refraction, showOutlines],
  );
  return (
    <GlassSettingsContext.Provider value={value}>
      {children}
    </GlassSettingsContext.Provider>
  );
}

export interface GlassSceneContextValue {
  source: RefObject<HTMLDivElement | null>;
  config?: Partial<LensParams>;
  frameRate?: number;
  appearance?: "light" | "dark";
  live?: boolean;
}
const GlassSceneContext = createContext<GlassSceneContextValue | null>(null);
export function useGlassScene() {
  return useContext(GlassSceneContext);
}

export interface GlassSceneProps
  extends Omit<HTMLAttributes<HTMLDivElement>, "content"> {
  /** The complete, interactive DOM backdrop. Lenses go in children. */
  content: ReactNode;
  sourceClassName?: string;
  /** Optional ref to the original scene, for contrast sampling or explicit invalidation. */
  sourceRef?: RefObject<HTMLDivElement | null>;
  config?: Partial<LensParams>;
  frameRate?: number;
  appearance?: "light" | "dark";
  /** Poll adaptive ink only for continuously animated or video sources. */
  live?: boolean;
}

/** One bounded source scene, shared by every descendant glass lens. */
export function GlassScene({
  content,
  children,
  sourceClassName,
  sourceRef,
  frameRate,
  config,
  appearance,
  live = false,
  style,
  ...props
}: GlassSceneProps) {
  const localSource = useRef<HTMLDivElement>(null);
  const source = sourceRef ?? localSource;
  const value = useMemo(
    () => ({ source, frameRate, config, appearance, live }),
    [source, frameRate, config, appearance, live],
  );
  return (
    <GlassSceneContext.Provider value={value}>
      <div
        {...props}
        data-glass-scene=""
        style={{ position: "relative", ...style }}
      >
        <div
          ref={source}
          data-glass-scene-source=""
          className={sourceClassName}
          style={{ position: "absolute", inset: 0 }}
        >
          {content}
        </div>
        {children}
      </div>
    </GlassSceneContext.Provider>
  );
}

"use client";

import { useEffect, useState, type RefObject } from "react";

export interface BackdropPlane {
  src: string;
  width: number;
  height: number;
  x: number;
  y: number;
}

/** Align an opt-in image backdrop to the glass in CSS pixels. Unlike SVG
 * backdrop-filter references, filtering an explicit source works in WebKit
 * and Gecko too. No DOM screenshots or asynchronous raster snapshots.
 */
export function useBackdropPlane(
  surface: RefObject<HTMLElement | null>,
  source: RefObject<HTMLImageElement | null> | undefined,
  pad: number,
): BackdropPlane | null {
  const [plane, setPlane] = useState<BackdropPlane | null>(null);
  useEffect(() => {
    const element = surface.current;
    const image = source?.current;
    if (!element || !image) return;
    let frame = 0;
    const update = () => {
      if (!image.complete || !image.naturalWidth) return;
      const imageRect = image.getBoundingClientRect();
      const glassRect = element.getBoundingClientRect();
      if (!imageRect.width || !imageRect.height) return;
      const style = getComputedStyle(image);
      const fit = style.objectFit;
      const cover = Math.max(imageRect.width / image.naturalWidth, imageRect.height / image.naturalHeight);
      const contain = Math.min(imageRect.width / image.naturalWidth, imageRect.height / image.naturalHeight);
      const scale = fit === "cover" ? cover : fit === "contain" ? contain : fit === "scale-down" ? Math.min(1, contain) : 1;
      const width = fit === "fill" ? imageRect.width : image.naturalWidth * scale;
      const height = fit === "fill" ? imageRect.height : image.naturalHeight * scale;
      const [horizontal = "50%", vertical = "50%"] = style.objectPosition.split(/\s+/);
      const position = (value: string, free: number) => {
        if (value === "center") return free / 2;
        if (value === "right" || value === "bottom") return free;
        if (value === "left" || value === "top") return 0;
        return value.endsWith("%") ? free * parseFloat(value) / 100 : parseFloat(value) || 0;
      };
      const next = {
        src: image.currentSrc || image.src,
        width,
        height,
        x: imageRect.left - glassRect.left - element.clientLeft + pad + position(horizontal, imageRect.width - width),
        y: imageRect.top - glassRect.top - element.clientTop + pad + position(vertical, imageRect.height - height),
      };
      setPlane((previous) => previous && Object.keys(next).every((key) => previous[key as keyof BackdropPlane] === next[key as keyof BackdropPlane]) ? previous : next);
    };
    const schedule = () => { cancelAnimationFrame(frame); frame = requestAnimationFrame(update); };
    const observer = new ResizeObserver(schedule);
    observer.observe(element);
    observer.observe(image);
    image.addEventListener("load", schedule);
    // Layout shifts and object-fit/source changes also alter the mapping.
    const mutations = new MutationObserver(schedule);
    mutations.observe(image, { attributes: true, attributeFilter: ["style", "class", "src", "srcset", "sizes"] });
    window.addEventListener("resize", schedule);
    window.addEventListener("scroll", schedule, { passive: true, capture: true });
    update();
    return () => {
      cancelAnimationFrame(frame);
      observer.disconnect();
      mutations.disconnect();
      image.removeEventListener("load", schedule);
      window.removeEventListener("resize", schedule);
      window.removeEventListener("scroll", schedule, true);
    };
  }, [surface, source, pad]);
  return source ? plane : null;
}

/**
 * Contrast engine for adaptive ink.
 *
 * The sampler reads the *actual* backdrop behind a piece of text — canvas
 * pixels when available, otherwise resolved CSS paints (background-color and
 * gradient stops) composited with source-over alpha — then decides whether
 * light or dark ink yields the higher WCAG contrast ratio.
 */

export type ContrastTone = "light" | "dark";

export interface Rgba {
  r: number;
  g: number;
  b: number;
  a: number;
}

export interface ContrastSample {
  /** Mean relative luminance (0..1) of the backdrop under the element. */
  luminance: number;
  tone: ContrastTone;
  /** WCAG contrast ratio for the chosen ink. */
  contrast: number;
  /** WCAG contrast ratio of the ink that was *not* chosen. */
  rejectedContrast: number;
  /** How many probe points contributed. */
  samples: number;
  /** Readability overlay needed for the selected ink (0 means clear glass). */
  scrimOpacity?: number;
  /** An enclosing surface already owns the ink and its protection. */
  inherited?: boolean;
}

export const WHITE_INK = "#ffffff";
export const BLACK_INK = "#000000";

const INK_FLIP_LUMINANCE = 0.1791;
const DEFAULT_LUMINANCE = 0.02;

export function channelToLinear(channel: number): number {
  const c = channel / 255;
  return c <= 0.04045 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4);
}

export function relativeLuminance(color: Pick<Rgba, "r" | "g" | "b">): number {
  return (
    0.2126 * channelToLinear(color.r) +
    0.7152 * channelToLinear(color.g) +
    0.0722 * channelToLinear(color.b)
  );
}

export function contrastRatio(a: number, b: number): number {
  const hi = Math.max(a, b);
  const lo = Math.min(a, b);
  return (hi + 0.05) / (lo + 0.05);
}

/** Source-over: `top` painted above `bottom`. */
export function composite(top: Rgba, bottom: Rgba): Rgba {
  const a = top.a + bottom.a * (1 - top.a);
  if (a <= 0) return { r: 0, g: 0, b: 0, a: 0 };
  return {
    a,
    r: (top.r * top.a + bottom.r * bottom.a * (1 - top.a)) / a,
    g: (top.g * top.a + bottom.g * bottom.a * (1 - top.a)) / a,
    b: (top.b * top.a + bottom.b * bottom.a * (1 - top.a)) / a,
  };
}

export function averageColors(colors: Rgba[]): Rgba | null {
  if (colors.length === 0) return null;
  if (colors.length === 1) return colors[0];
  let a = 0;
  let r = 0;
  let g = 0;
  let b = 0;
  for (const c of colors) {
    a += c.a;
    r += c.r * c.a;
    g += c.g * c.a;
    b += c.b * c.a;
  }
  if (a <= 0) return { r: 0, g: 0, b: 0, a: 0 };
  return { r: r / a, g: g / a, b: b / a, a: a / colors.length };
}

export function toneForLuminance(luminance: number): ContrastTone {
  return luminance < INK_FLIP_LUMINANCE ? "light" : "dark";
}

export function sampleFromLuminance(
  luminance: number,
  samples: number,
): ContrastSample {
  const tone = toneForLuminance(luminance);
  const light = contrastRatio(luminance, 1);
  const dark = contrastRatio(luminance, 0);
  return {
    luminance,
    tone,
    contrast: tone === "light" ? light : dark,
    rejectedContrast: tone === "light" ? dark : light,
    samples,
  };
}

/* ------------------------------------------------------------------ colors */

let colorContext: CanvasRenderingContext2D | null | undefined;

function getColorContext(): CanvasRenderingContext2D | null {
  if (colorContext !== undefined) return colorContext;
  if (typeof document === "undefined") {
    colorContext = null;
    return null;
  }
  const canvas = document.createElement("canvas");
  canvas.width = 1;
  canvas.height = 1;
  colorContext = canvas.getContext("2d", { willReadFrequently: true });
  return colorContext;
}

/** Resolve any CSS color string to straight (un-premultiplied) sRGB bytes. */
export function parseCssColor(value: string): Rgba | null {
  const color = value.trim();
  if (!color || color === "none" || color === "currentcolor") return null;
  const ctx = getColorContext();
  if (!ctx) return null;
  if (
    typeof CSS !== "undefined" &&
    CSS.supports &&
    !CSS.supports("color", color)
  ) {
    return null;
  }
  try {
    ctx.clearRect(0, 0, 1, 1);
    ctx.fillStyle = "#000000";
    ctx.fillStyle = color;
    ctx.fillRect(0, 0, 1, 1);
    const data = ctx.getImageData(0, 0, 1, 1).data;
    return { r: data[0], g: data[1], b: data[2], a: data[3] / 255 };
  } catch {
    return null;
  }
}

const COLOR_FN =
  /(rgba?|hsla?|oklch|oklab|lab|lch|color|color-mix|light-dark)\s*\(/gi;
const HEX = /#[0-9a-fA-F]{3,8}\b/g;

/**
 * Pull every color token out of a computed `background-image` value. Handles
 * nested functions (e.g. `color-mix(...)`) by balancing parentheses.
 */
export function extractCssColors(input: string): Rgba[] {
  const out: Rgba[] = [];
  COLOR_FN.lastIndex = 0;
  let match: RegExpExecArray | null;
  while ((match = COLOR_FN.exec(input))) {
    const start = match.index + match[0].length - 1;
    let depth = 0;
    let end = -1;
    for (let i = start; i < input.length; i++) {
      const ch = input[i];
      if (ch === "(") depth++;
      else if (ch === ")") {
        depth--;
        if (depth === 0) {
          end = i + 1;
          break;
        }
      }
    }
    if (end < 0) continue;
    const parsed = parseCssColor(input.slice(match.index, end));
    if (parsed) out.push(parsed);
    COLOR_FN.lastIndex = end;
  }
  HEX.lastIndex = 0;
  while ((match = HEX.exec(input))) {
    const parsed = parseCssColor(match[0]);
    if (parsed && parsed.a > 0) out.push(parsed);
  }
  return out;
}

function splitCssList(input: string): string[] {
  const parts: string[] = [];
  let depth = 0;
  let quote = "";
  let start = 0;
  for (let i = 0; i < input.length; i++) {
    const ch = input[i];
    if (quote) {
      if (ch === quote && input[i - 1] !== "\\") quote = "";
      continue;
    }
    if (ch === "'" || ch === '"') quote = ch;
    else if (ch === "(") depth++;
    else if (ch === ")") depth--;
    else if (ch === "," && depth === 0) {
      parts.push(input.slice(start, i).trim());
      start = i + 1;
    }
  }
  if (start < input.length) parts.push(input.slice(start).trim());
  return parts.filter(Boolean);
}

function readColorToken(value: string): { color: Rgba; rest: string } | null {
  const input = value.trimStart();
  const leading = value.length - input.length;
  let token = "";
  if (input.startsWith("#")) {
    token = /^#[\da-f]{3,8}/i.exec(input)?.[0] ?? "";
  } else {
    const fn = /^([a-z][\w-]*)\(/i.exec(input);
    if (fn) {
      let depth = 0;
      for (let i = fn[0].length - 1; i < input.length; i++) {
        if (input[i] === "(") depth++;
        else if (input[i] === ")" && --depth === 0) {
          token = input.slice(0, i + 1);
          break;
        }
      }
    } else {
      const word = /^[a-z]+/i.exec(input)?.[0] ?? "";
      if (word && typeof CSS !== "undefined" && CSS.supports?.("color", word)) {
        token = word;
      }
    }
  }
  if (!token) return null;
  const color = parseCssColor(token);
  return color ? { color, rest: value.slice(leading + token.length) } : null;
}

interface ColorStop {
  color: Rgba;
  position: number;
}

function parseColorStops(parts: string[]): ColorStop[] {
  const stops = parts.flatMap((part) => {
    const parsed = readColorToken(part);
    if (!parsed) return [];
    const positions = [...parsed.rest.matchAll(/(-?(?:\d*\.)?\d+)%/g)];
    return [
      {
        color: parsed.color,
        position: positions.length ? Number(positions[0][1]) / 100 : Number.NaN,
      },
    ];
  });
  if (stops.length < 2) return stops;
  if (!Number.isFinite(stops[0].position)) stops[0].position = 0;
  if (!Number.isFinite(stops.at(-1)?.position))
    stops[stops.length - 1].position = 1;
  let previous = 0;
  while (previous < stops.length - 1) {
    let next = previous + 1;
    while (next < stops.length - 1 && !Number.isFinite(stops[next].position))
      next++;
    const start = stops[previous].position;
    const end = stops[next].position;
    for (let i = previous + 1; i < next; i++) {
      stops[i].position =
        start + ((end - start) * (i - previous)) / (next - previous);
    }
    previous = next;
  }
  return stops;
}

function sampleStops(stops: ColorStop[], t: number): Rgba | null {
  if (!stops.length) return null;
  const value = Math.max(0, Math.min(1, t));
  const right = stops.findIndex((stop) => stop.position >= value);
  if (right < 0) return stops.at(-1)!.color;
  if (right === 0) return stops[0].color;
  const left = stops[right - 1];
  const next = stops[right];
  const span = next.position - left.position;
  const mix = span <= 0 ? 1 : (value - left.position) / span;
  return {
    r: left.color.r + (next.color.r - left.color.r) * mix,
    g: left.color.g + (next.color.g - left.color.g) * mix,
    b: left.color.b + (next.color.b - left.color.b) * mix,
    a: left.color.a + (next.color.a - left.color.a) * mix,
  };
}

function descriptorCoordinate(
  value: string | undefined,
  axis: "x" | "y",
): number {
  if (!value) return 0.5;
  const keyword = value.trim().toLowerCase();
  if (keyword === "left" || keyword === "top") return 0;
  if (keyword === "right" || keyword === "bottom") return 1;
  if (keyword === "center") return 0.5;
  const percent = /(-?(?:\d*\.)?\d+)%/.exec(keyword);
  if (percent) return Number(percent[1]) / 100;
  return axis === "x" ? 0.5 : 0.5;
}

function sampleGradient(
  image: string,
  x: number,
  y: number,
  width: number,
  height: number,
): Rgba | null {
  const match = /^(?:repeating-)?(linear|radial|conic)-gradient\((.*)\)$/i.exec(
    image.trim(),
  );
  if (!match) return null;
  const kind = match[1].toLowerCase();
  const parts = splitCssList(match[2]);
  if (!parts.length) return null;
  const descriptor = readColorToken(parts[0]) ? "" : (parts.shift() ?? "");
  const stops = parseColorStops(parts);
  if (!stops.length) return null;

  let t = 0.5;
  if (kind === "linear") {
    let angle = 180;
    const degrees = /(-?(?:\d*\.)?\d+)deg/i.exec(descriptor);
    if (degrees) angle = Number(degrees[1]);
    else if (/to\s+top/i.test(descriptor)) angle = 0;
    else if (/to\s+right/i.test(descriptor)) angle = 90;
    else if (/to\s+left/i.test(descriptor)) angle = 270;
    else if (/to\s+bottom/i.test(descriptor)) angle = 180;
    const radians = (angle * Math.PI) / 180;
    const dx = Math.sin(radians);
    const dy = -Math.cos(radians);
    const lineLength = Math.max(
      1,
      Math.abs(dx) * width + Math.abs(dy) * height,
    );
    t = 0.5 + ((x - 0.5) * width * dx + (y - 0.5) * height * dy) / lineLength;
  } else if (kind === "radial") {
    const at = /\bat\s+([\w.%+-]+)(?:\s+([\w.%+-]+))?/i.exec(descriptor);
    const cx = descriptorCoordinate(at?.[1], "x");
    const cy = descriptorCoordinate(at?.[2], "y");
    const sizeDescriptor = descriptor.split(/\bat\b/i)[0];
    const radii = sizeDescriptor.match(
      /(-?(?:\d*\.)?\d+)%\s+(-?(?:\d*\.)?\d+)%/i,
    );
    const rx = radii?.[1] ? (Number(radii[1]) / 100) * width : width / 2;
    const ry = radii?.[2] ? (Number(radii[2]) / 100) * height : height / 2;
    t = Math.hypot(
      ((x - cx) * width) / Math.max(1, rx),
      ((y - cy) * height) / Math.max(1, ry),
    );
  } else {
    const at = /\bat\s+([\w.%+-]+)(?:\s+([\w.%+-]+))?/i.exec(descriptor);
    const cx = descriptorCoordinate(at?.[1], "x");
    const cy = descriptorCoordinate(at?.[2], "y");
    t = (Math.atan2(y - cy, x - cx) / (2 * Math.PI) + 1) % 1;
  }
  return sampleStops(stops, t);
}

function sampleBackgroundImage(
  image: string,
  x: number,
  y: number,
  width: number,
  height: number,
): Rgba | null {
  let result: Rgba | null = null;
  const layers = splitCssList(image);
  for (let i = layers.length - 1; i >= 0; i--) {
    const paint = sampleGradient(layers[i], x, y, width, height);
    if (paint) result = result ? composite(paint, result) : paint;
  }
  return result;
}

/* --------------------------------------------------------------- sampling */

function readCanvasPixel(
  canvas: HTMLCanvasElement,
  x: number,
  y: number,
): Rgba | null {
  try {
    const rect = canvas.getBoundingClientRect();
    if (rect.width < 1 || rect.height < 1) return null;
    const sx = Math.floor(((x - rect.left) / rect.width) * canvas.width);
    const sy = Math.floor(((y - rect.top) / rect.height) * canvas.height);
    if (sx < 0 || sy < 0 || sx >= canvas.width || sy >= canvas.height)
      return null;
    const ctx = canvas.getContext("2d", { willReadFrequently: true });
    if (!ctx) return null;
    const data = ctx.getImageData(sx, sy, 1, 1).data;
    return { r: data[0], g: data[1], b: data[2], a: data[3] / 255 };
  } catch {
    return null;
  }
}

function paintFor(
  node: Element,
  x: number,
  y: number,
  computed?: CSSStyleDeclaration,
): Rgba | null {
  if (node instanceof HTMLCanvasElement) {
    return null; // handled separately (per-pixel)
  }
  let style: CSSStyleDeclaration;
  try {
    style = computed ?? getComputedStyle(node);
  } catch {
    return null;
  }
  const background = parseCssColor(style.backgroundColor);
  const hasImage = style.backgroundImage && style.backgroundImage !== "none";
  let paint: Rgba | null =
    background && background.a > 0.001 ? background : null;
  if (hasImage) {
    const rect = node.getBoundingClientRect();
    const imagePaint = sampleBackgroundImage(
      style.backgroundImage,
      rect.width ? (x - rect.left) / rect.width : 0.5,
      rect.height ? (y - rect.top) / rect.height : 0.5,
      rect.width,
      rect.height,
    );
    if (imagePaint) paint = paint ? composite(imagePaint, paint) : imagePaint;
  }
  return paint;
}

let imageSampleCanvas: HTMLCanvasElement | null = null;

function objectPosition(value: string, axis: "x" | "y"): number {
  const parts = value.split(/\s+/);
  const token = axis === "x" ? parts[0] : (parts[1] ?? parts[0]);
  if (token === "left" || token === "top") return 0;
  if (token === "right" || token === "bottom") return 1;
  const percent = /(-?(?:\d*\.)?\d+)%/.exec(token ?? "");
  return percent ? Number(percent[1]) / 100 : 0.5;
}

function readImagePixel(
  image: HTMLImageElement | HTMLVideoElement,
  x: number,
  y: number,
  bounds?: DOMRect,
  computed?: CSSStyleDeclaration,
): Rgba | null {
  const rect = bounds ?? image.getBoundingClientRect();
  const sourceWidth =
    image instanceof HTMLImageElement ? image.naturalWidth : image.videoWidth;
  const sourceHeight =
    image instanceof HTMLImageElement ? image.naturalHeight : image.videoHeight;
  if (rect.width < 1 || rect.height < 1 || sourceWidth < 1 || sourceHeight < 1)
    return null;
  if (image instanceof HTMLImageElement && !image.complete) return null;
  if (
    image instanceof HTMLVideoElement &&
    image.readyState < HTMLMediaElement.HAVE_CURRENT_DATA
  )
    return null;

  let sx = ((x - rect.left) / rect.width) * sourceWidth;
  let sy = ((y - rect.top) / rect.height) * sourceHeight;
  const style = computed ?? getComputedStyle(image);
  const fit = style.objectFit;
  if (fit === "cover" || fit === "contain") {
    const scale =
      fit === "cover"
        ? Math.max(rect.width / sourceWidth, rect.height / sourceHeight)
        : Math.min(rect.width / sourceWidth, rect.height / sourceHeight);
    const renderedWidth = sourceWidth * scale;
    const renderedHeight = sourceHeight * scale;
    const offsetX =
      (rect.width - renderedWidth) * objectPosition(style.objectPosition, "x");
    const offsetY =
      (rect.height - renderedHeight) *
      objectPosition(style.objectPosition, "y");
    sx = (x - rect.left - offsetX) / scale;
    sy = (y - rect.top - offsetY) / scale;
    if (sx < 0 || sy < 0 || sx >= sourceWidth || sy >= sourceHeight) {
      return { r: 0, g: 0, b: 0, a: 0 };
    }
  }
  if (sx < 0 || sy < 0 || sx >= sourceWidth || sy >= sourceHeight) return null;
  try {
    imageSampleCanvas ??= document.createElement("canvas");
    imageSampleCanvas.width = 1;
    imageSampleCanvas.height = 1;
    const ctx = imageSampleCanvas.getContext("2d", {
      willReadFrequently: true,
    });
    if (!ctx) return null;
    ctx.clearRect(0, 0, 1, 1);
    ctx.drawImage(image, sx, sy, 1, 1, 0, 0, 1, 1);
    const data = ctx.getImageData(0, 0, 1, 1).data;
    return { r: data[0], g: data[1], b: data[2], a: data[3] / 255 };
  } catch {
    // Cross-origin images without CORS permission cannot be read. The sampler
    // continues with the next available CSS layer instead.
    return null;
  }
}

export interface SampleOptions {
  /** Sample the same original DOM used by the lens, including non-hit-testable layers. */
  source?: HTMLElement | null;
  /** Optional material tint composited over sampled paints. */
  tintColor?: string;
  tintOpacity?: number;
  /** Probe grid resolution (default 5). */
  resolution?: number;
  /** Fraction of the element inset before sampling (default 0.06). */
  inset?: number;
  /** Optional fixed ink. Still measures protection needed for readability. */
  tone?: ContrastTone;
  brightness?: number;
  contrast?: number;
  saturate?: number;
  tintBlendMode?: string;
}

function filterPaint(color: Rgba, options: SampleOptions, tint?: Rgba): Rgba {
  const saturation = options.saturate ?? 1;
  const brightness = options.brightness ?? 1;
  const contrast = options.contrast ?? 1;
  const gray = 0.213 * color.r + 0.715 * color.g + 0.072 * color.b;
  const channel = (value: number) =>
    Math.max(
      0,
      Math.min(
        255,
        ((gray + (value - gray) * saturation) * brightness - 127.5) * contrast +
          127.5,
      ),
    );
  const filtered = {
    ...color,
    r: channel(color.r),
    g: channel(color.g),
    b: channel(color.b),
  };
  if (!tint) return filtered;
  return composite(
    options.tintBlendMode === "multiply"
      ? {
          ...tint,
          r: (tint.r * filtered.r) / 255,
          g: (tint.g * filtered.g) / 255,
          b: (tint.b * filtered.b) / 255,
        }
      : tint,
    filtered,
  );
}

const transparent: Rgba = { r: 0, g: 0, b: 0, a: 0 };
interface PaintNode {
  element: Element;
  style: CSSStyleDeclaration;
  rect: DOMRect;
  children: PaintNode[];
}

// Geometry is read once per measurement, never once per probe. Reading the
// original source also works when a modal makes it inert or pointer-events:none.
function prepareSource(element: Element): PaintNode | null {
  if (
    element.matches(
      "[data-liquid-glass], [data-glass-mirror-host], [data-adaptive-skip]",
    )
  )
    return null;
  const style = getComputedStyle(element);
  if (
    style.display === "none" ||
    style.visibility === "hidden" ||
    Number(style.opacity) === 0
  )
    return null;
  const children = [...element.children]
    .map(prepareSource)
    .filter((child): child is PaintNode => child !== null)
    .sort(
      (a, b) =>
        (Number.parseInt(a.style.zIndex) || 0) -
        (Number.parseInt(b.style.zIndex) || 0),
    );
  return { element, style, rect: element.getBoundingClientRect(), children };
}

interface PaintSample {
  color: Rgba;
  unknown: boolean;
}
function paintSource(node: PaintNode, x: number, y: number): PaintSample {
  const { element, rect, style } = node;
  const insideX = x >= rect.left && x < rect.right;
  const insideY = y >= rect.top && y < rect.bottom;
  if (
    (!insideX && /hidden|clip|scroll|auto/.test(style.overflowX)) ||
    (!insideY && /hidden|clip|scroll|auto/.test(style.overflowY))
  )
    return { color: transparent, unknown: false };
  let color = transparent;
  let unknown = false;
  if (insideX && insideY) {
    color = paintFor(element, x, y, style) ?? transparent;
    // CSS URL paints cannot be synchronously inspected without loading another
    // image. Treat them as unknown rather than sampling the page underneath.
    unknown = style.backgroundImage.includes("url(");
    if (
      element instanceof HTMLImageElement ||
      element instanceof HTMLVideoElement ||
      element instanceof HTMLCanvasElement
    ) {
      const pixel =
        element instanceof HTMLCanvasElement
          ? readCanvasPixel(element, x, y)
          : readImagePixel(element, x, y, rect, style);
      if (pixel) {
        color = composite(pixel, color);
        if (pixel.a >= 0.999) unknown = false;
      } else unknown = true;
    }
  }
  for (const child of node.children) {
    const paint = paintSource(child, x, y);
    color = composite(paint.color, color);
    unknown = paint.unknown || (unknown && paint.color.a < 0.999);
  }
  return {
    color: { ...color, a: color.a * Number.parseFloat(style.opacity || "1") },
    unknown,
  };
}

/** Smallest neutral overlay that protects the sampled points, in sRGB. */
function protectionFor(colors: Rgba[], tone: ContrastTone): number {
  const ink = tone === "light" ? 1 : 0;
  const channel = tone === "light" ? 0 : 255;
  for (let step = 0; step <= 80; step++) {
    const alpha = step / 100;
    if (
      colors.every(
        (color) =>
          contrastRatio(
            relativeLuminance(
              composite(
                { r: channel, g: channel, b: channel, a: alpha },
                color,
              ),
            ),
            ink,
          ) >= 4.8,
      )
    )
      return alpha;
  }
  return 0.8;
}

/** Sample the composited backdrop luminance behind `el`. */
export function sampleBackdrop(
  el: HTMLElement,
  options: SampleOptions = {},
): ContrastSample {
  if (typeof document === "undefined" || typeof window === "undefined") {
    return sampleFromLuminance(DEFAULT_LUMINANCE, 0);
  }
  const rect = el.getBoundingClientRect();
  // Only inherit an explicit tone from an ancestor. Reading the element's own
  // data attribute would feed its previous answer back into the next sample.
  const explicit =
    !options.source &&
    el.parentElement?.closest<HTMLElement>("[data-adaptive-tone]")?.dataset
      .adaptiveTone;
  if (explicit === "light" || explicit === "dark") {
    const ink = explicit === "light" ? 1 : 0;
    return {
      ...sampleFromLuminance(ink === 1 ? 0.01 : 0.6, 0),
      inherited: true,
      scrimOpacity: 0,
    };
  }
  if (rect.width < 2 || rect.height < 2) {
    return sampleFromLuminance(DEFAULT_LUMINANCE, 0);
  }

  const resolution = Math.max(
    2,
    Math.min(
      9,
      Math.floor(Number.isFinite(options.resolution) ? options.resolution! : 5),
    ),
  );
  const inset = Math.max(
    0,
    Math.min(0.49, Number.isFinite(options.inset) ? options.inset! : 0.06),
  );
  const left = rect.left + rect.width * inset;
  const top = rect.top + rect.height * inset;
  const width = Math.max(1, rect.width * (1 - inset * 2));
  const height = Math.max(1, rect.height * (1 - inset * 2));

  const tintColor = options.tintColor ? parseCssColor(options.tintColor) : null;
  const tint = tintColor
    ? { ...tintColor, a: Math.max(0, Math.min(1, options.tintOpacity ?? 0)) }
    : undefined;
  const source = options.source ? prepareSource(options.source) : null;
  if (options.source && !source)
    return sampleFromLuminance(DEFAULT_LUMINANCE, 0);
  const colors: Rgba[] = [];
  let unavailable = false;
  let sum = 0;
  let darkest = 1;
  let lightest = 0;
  let count = 0;
  for (let row = 0; row < resolution; row++) {
    for (let col = 0; col < resolution; col++) {
      const x = left + ((col + 0.5) / resolution) * width;
      const y = top + ((row + 0.5) / resolution) * height;
      const paint = source ? paintSource(source, x, y) : null;
      if (paint?.unknown) unavailable = true;
      const raw = paint
        ? paint.unknown || paint.color.a < 0.985
          ? null
          : paint.color
        : colorAtPoint(x, y, el);
      const color = raw ? filterPaint(raw, options, tint) : null;
      const luminance = color ? relativeLuminance(color) : null;
      if (luminance === null) continue;
      colors.push(color!);
      sum += luminance;
      darkest = Math.min(darkest, luminance);
      lightest = Math.max(lightest, luminance);
      count++;
    }
  }
  if (count === 0 || unavailable)
    return sampleFromLuminance(DEFAULT_LUMINANCE, 0);
  const mean = sum / count;
  const averageChoice = sampleFromLuminance(mean, count);
  const whiteWorstCase = contrastRatio(lightest, 1);
  const blackWorstCase = contrastRatio(darkest, 0);
  const tone =
    options.tone ??
    (Math.abs(whiteWorstCase - blackWorstCase) < 0.12
      ? averageChoice.tone
      : whiteWorstCase > blackWorstCase
        ? "light"
        : "dark");
  return {
    luminance: mean,
    tone,
    contrast: tone === "light" ? whiteWorstCase : blackWorstCase,
    rejectedContrast: tone === "light" ? blackWorstCase : whiteWorstCase,
    samples: count,
    scrimOpacity: protectionFor(colors, tone),
  };
}

function colorAtPoint(
  x: number,
  y: number,
  exclude: HTMLElement,
  tint?: Rgba,
): Rgba | null {
  let stack: Element[];
  try {
    stack = document.elementsFromPoint(x, y);
  } catch {
    return null;
  }
  const layers: Rgba[] = [];
  let alpha = 0;
  // Hit testing returns front-to-back. Collect visible layers in that order,
  // stop at an opaque layer, then composite back-to-front.
  for (let i = 0; i < stack.length; i++) {
    const node = stack[i];
    if (node === exclude || exclude.contains(node)) continue;
    if (node instanceof HTMLElement && node.dataset.adaptiveSkip !== undefined)
      continue;
    if (node instanceof HTMLCanvasElement) {
      const pixel = readCanvasPixel(node, x, y);
      if (pixel && pixel.a > 0.01) {
        layers.push(pixel);
        alpha = alpha + pixel.a * (1 - alpha);
        if (alpha >= 0.985) break;
      }
      continue;
    }
    if (node instanceof HTMLImageElement || node instanceof HTMLVideoElement) {
      const pixel = readImagePixel(node, x, y);
      if (pixel && pixel.a > 0.01) {
        const opacity = Number.parseFloat(
          getComputedStyle(node).opacity || "1",
        );
        const paint = { ...pixel, a: pixel.a * opacity };
        layers.push(paint);
        alpha = alpha + paint.a * (1 - alpha);
        if (alpha >= 0.985) break;
        continue;
      }
      // Never infer the image's color from an unrelated layer underneath it.
      return null;
    }
    const style = getComputedStyle(node);
    if (style.backgroundImage.includes("url(")) return null;
    const raw = paintFor(node, x, y, style);
    const paint = raw
      ? { ...raw, a: raw.a * Number.parseFloat(style.opacity || "1") }
      : null;
    if (paint && paint.a > 0.004) {
      layers.push(paint);
      alpha = alpha + paint.a * (1 - alpha);
      if (alpha >= 0.985) break;
    }
  }
  if (layers.length === 0) return null;
  let result: Rgba = { r: 0, g: 0, b: 0, a: 0 };
  for (const layer of layers.reverse()) result = composite(layer, result);
  if (result.a < 0.35) return null;
  return tint ? composite(tint, result) : result;
}

"use client";

import * as React from "react";
import { cn } from "@/lib/utils";
import {
  BLACK_INK,
  WHITE_INK,
  sampleBackdrop,
  sampleFromLuminance,
  type ContrastSample,
} from "@/lib/contrast";

export interface UseAdaptiveContrastOptions {
  /** Enable sampling. Fixed-theme consumers can opt out. */
  enabled?: boolean;
  /** Keep a chosen ink while computing the readability protection it needs. */
  tone?: "light" | "dark";
  /** The original DOM source used by the refraction engine. */
  source?: React.RefObject<HTMLElement | null>;
  /** Re-measure continuously (for animated backdrops). */
  live?: boolean;
  /** Minimum ms between live measurements. */
  interval?: number;
  /** Pixels per row and column sampled across the target region. */
  resolution?: number;
  tintColor?: string;
  tintBlendMode?: string;
  brightness?: number;
  contrast?: number;
  saturate?: number;
  tintOpacity?: number;
  /** Used before measurement and when pixels are unavailable. */
  fallback?: ContrastSample;
}

/**
 * Measures the backdrop behind `ref` and resolves the ink color that reads
 * best against it. Static elements re-measure on scroll/resize; `live`
 * elements also poll on an animation frame (for moving backgrounds/canvas).
 */
export function useAdaptiveContrast(
  ref: React.RefObject<HTMLElement | null>,
  {
    enabled = true,
    tone,
    source,
    live = false,
    interval = 240,
    resolution = 3,
    tintColor,
    tintOpacity = 0,
    tintBlendMode,
    brightness,
    contrast,
    saturate,
    fallback,
  }: UseAdaptiveContrastOptions = {},
): ContrastSample {
  const initial = fallback ?? sampleFromLuminance(0.02, 0);
  const [sample, setSample] = React.useState<ContrastSample>(initial);
  const previous = React.useRef<ContrastSample>(initial);

  React.useEffect(() => {
    const el = ref.current;
    if (!enabled || !el || typeof window === "undefined") return;
    let timer: ReturnType<typeof setTimeout> | undefined;
    let frame = 0;
    let visible = true;
    let disposed = false;
    const delay = Math.max(100, interval);
    const measure = () => {
      if (disposed || !visible || document.hidden) return;
      const options = {
        source: source?.current,
        resolution,
        tone,
        tintColor,
        tintOpacity,
        tintBlendMode,
        brightness,
        contrast,
        saturate,
      };
      let next = sampleBackdrop(el, options);
      const prev = previous.current;
      // Hysteresis must also recompute the protection for the retained ink.
      if (
        !tone &&
        next.samples &&
        prev.samples &&
        prev.tone !== next.tone &&
        next.contrast < next.rejectedContrast + 0.7
      ) {
        next = sampleBackdrop(el, { ...options, tone: prev.tone });
      }
      previous.current = next;
      setSample((value) =>
        value.tone === next.tone &&
        value.samples === next.samples &&
        value.inherited === next.inherited &&
        value.scrimOpacity === next.scrimOpacity &&
        Math.abs(value.luminance - next.luminance) < 0.008 &&
        Math.abs(value.contrast - next.contrast) < 0.08
          ? value
          : next,
      );
    };
    const tick = () => {
      measure();
      if (live && visible && !document.hidden && !disposed)
        timer = setTimeout(tick, delay);
    };
    const queue = () => {
      cancelAnimationFrame(frame);
      frame = requestAnimationFrame(measure);
    };
    const restart = () => {
      clearTimeout(timer);
      tick();
    };
    const onLoad=(event:Event)=>{
      if(event.target instanceof Element && event.target.closest("[data-glass-mirror-host],[data-glass-mirror]"))return;
      queue();
    };
    const position=typeof MutationObserver!=="undefined" ? new MutationObserver(queue) : null;
    position?.observe(el,{attributes:true,attributeFilter:["style","class"]});
    const mutations =
      typeof MutationObserver !== "undefined"
        ? new MutationObserver((records) => {
            if (
              records.every(
                (record) =>
                  record.target === el ||
                  el.contains(record.target as Node) ||
                  (record.target instanceof Element &&
                    record.target.closest("[data-glass-mirror-host]")),
              )
            )
              return;
            queue();
          })
        : null;
    mutations?.observe(source?.current ?? document.documentElement, {
      subtree: true,
      childList: true,
      attributes: true,
      attributeFilter: ["class", "style", "src", "srcset", "hidden"],
    });
    const resize =
      typeof ResizeObserver !== "undefined" ? new ResizeObserver(queue) : null;
    resize?.observe(el);
    if (source?.current) resize?.observe(source.current);
    const observer =
      typeof IntersectionObserver !== "undefined"
        ? new IntersectionObserver(([entry]) => {
            visible = entry.isIntersecting;
            restart();
          })
        : null;
    observer?.observe(el);
    window.addEventListener("scroll", queue, { passive: true, capture: true });
    window.addEventListener("resize", queue);
    document.addEventListener("load", onLoad, true);
    document.addEventListener("visibilitychange", restart);
    tick();
    return () => {
      disposed = true;
      clearTimeout(timer);
      cancelAnimationFrame(frame);
      observer?.disconnect();
      resize?.disconnect();
      mutations?.disconnect();
      position?.disconnect();
      window.removeEventListener("scroll", queue, true);
      window.removeEventListener("resize", queue);
      document.removeEventListener("load", onLoad, true);
      document.removeEventListener("visibilitychange", restart);
    };
  }, [
    ref,
    enabled,
    tone,
    source,
    live,
    interval,
    resolution,
    tintColor,
    tintOpacity,
    tintBlendMode,
    brightness,
    contrast,
    saturate,
  ]);

  return !enabled || (sample.samples === 0 && !sample.inherited)
    ? initial
    : sample;
}

export interface AdaptiveTextProps extends React.HTMLAttributes<HTMLElement> {
  as?: keyof React.JSX.IntrinsicElements;
  live?: boolean;
  interval?: number;
  /** Add a soft outline halo when sampled ink falls below 4.5:1. */
  halo?: boolean | "auto";
  /** Add a local adaptive scrim when neither ink reaches 4.5:1. */
  backplate?: boolean | "auto";
}

/**
 * Text whose color follows the contrast of whatever is behind it.
 * Renders a plain element and swaps between light/dark ink automatically.
 */
export function AdaptiveText({
  as = "span",
  live = false,
  interval,
  halo = "auto",
  backplate = "auto",
  className,
  style,
  children,
  ...rest
}: AdaptiveTextProps) {
  const ref = React.useRef<HTMLElement | null>(null);
  const sample = useAdaptiveContrast(ref, { live, interval });
  const Tag = as as React.ElementType;
  const ink = sample.tone === "light" ? WHITE_INK : BLACK_INK;
  const showBackplate =
    backplate === true || (backplate === "auto" && sample.contrast < 4.5);
  const showHalo = halo === true || (halo === "auto" && sample.contrast < 4.5);

  return (
    <Tag
      {...rest}
      ref={ref}
      data-adaptive-tone={sample.tone}
      data-adaptive-contrast={sample.contrast.toFixed(2)}
      className={cn("adaptive-ink", className)}
      style={{
        color: ink,
        display: showBackplate ? "inline-block" : undefined,
        maxWidth: showBackplate ? "100%" : undefined,
        padding: showBackplate ? "0.18em 0.48em" : undefined,
        borderRadius: showBackplate ? "0.7em" : undefined,
        border: showBackplate
          ? sample.tone === "light"
            ? "1px solid rgba(255,255,255,0.18)"
            : "1px solid rgba(0,0,0,0.12)"
          : undefined,
        backgroundColor: showBackplate
          ? sample.tone === "light"
            ? "rgba(7, 9, 13, 0.9)"
            : "rgba(255, 255, 255, 0.92)"
          : undefined,
        backdropFilter: showBackplate ? "blur(12px)" : undefined,
        WebkitBackdropFilter: showBackplate ? "blur(12px)" : undefined,
        boxShadow: showBackplate
          ? sample.tone === "light"
            ? "0 8px 30px rgba(0,0,0,0.2)"
            : "0 8px 30px rgba(0,0,0,0.12)"
          : undefined,
        textShadow: showHalo
          ? sample.tone === "light"
            ? "0 1px 2px rgba(0,0,0,0.6)"
            : "0 1px 2px rgba(255,255,255,0.55)"
          : undefined,
        ...style,
      }}
    >
      {children}
    </Tag>
  );
}

import { GLASS_PRESETS, type GlassPreset, type LensParams } from "@/lib/glass";

export type GlassMode = "light" | "dark";

export type GlassSurface = GlassPreset;

export const GLASS_SURFACES: readonly GlassSurface[] = [
  "transparent",
  "clear",
  "regular",
  "frosted",
  "thick",
];

export const SURFACE_LABELS: Record<GlassSurface, string> = {
  transparent: "Transparent",
  clear: "Clear",
  regular: "Regular",
  frosted: "Frosted",
  thick: "Thick",
};

/**
 * Dark-mode adjustments per surface. Dark glass reads best with a deep
 * neutral tint (instead of white), a touch less saturation/brightness and
 * softer glints.
 */
export const DARK_OVERRIDES: Record<GlassSurface, Partial<LensParams>> = {
  transparent: {
    tintColor: "#0b0c10",
    tint: 0.04,
    brightness: 1,
    glint: 40,
  },
  clear: {
