/**
 * Default lens radius per component family — one shared scale so every
 * component reads as the same design language:
 *   12 (controls) · 20 (panels and notifications)
 */
export const KIND_RADIUS: Record<GlassKind, number> = {
  navbar: 20,
  card: 26,
  dialog: 28,
  "alert-dialog": 28,
  sheet: 20,
  drawer: 28,
  popover: 22,
