};

export interface ResolvedGlassStyle {
  params: LensParams;
  radius: number;
}

export function resolveLensParams(
  surface: GlassSurface,
  mode?: GlassMode,
): LensParams {
  const base = GLASS_PRESETS[surface];
  if (mode !== "dark") return base;
  return { ...base, ...DARK_OVERRIDES[surface] };
}

export interface ResolveGlassOptions {
  kind: GlassKind;
  /** Explicit surface beats any context-level override or kind default. */
  surface?: GlassSurface;
  mode?: GlassMode;
  config?: Partial<LensParams>;
  radius?: number;
}

/**
 * Single source of truth for how a glass component looks:
 * kind default -> explicit override -> dark/light adaptation -> config tweak.
 */
export function resolveGlassStyle(
  opts: ResolveGlassOptions,
): ResolvedGlassStyle {
  const surface =
    opts.surface ?? KIND_SURFACE[opts.kind] ?? ("clear" as GlassSurface);
  return {
    params: { ...resolveLensParams(surface, opts.mode), ...opts.config },
    radius: opts.radius ?? KIND_RADIUS[opts.kind],
  };
}

"use client";

import {
  createContext,
  useContext,
  useEffect,
  useMemo,
  useSyncExternalStore,
  type ReactNode,
} from "react";
import type { GlassKind, GlassMode, GlassSurface } from "@/lib/glass-theme";

export type GlassModeSetting = GlassMode | "system";

const DEFAULT_MODE: GlassModeSetting = "light";
const MODE_KEY = "liquid-glass-mode";
const SURFACES_KEY = "liquid-glass-surfaces";

type SurfaceOverrides = Partial<Record<GlassKind, GlassSurface>>;

/* ------------------------------------------------------------------ store */

interface GlassStoreState {
  mode: GlassModeSetting;
  surfaces: SurfaceOverrides;
}

const serverState: GlassStoreState = { mode: DEFAULT_MODE, surfaces: {} };

function readInitialState(): GlassStoreState {
  if (typeof window === "undefined") return serverState;
  let mode: GlassModeSetting = DEFAULT_MODE;
  try {
    const v = localStorage.getItem(MODE_KEY);
    if (v === "light" || v === "dark" || v === "system") mode = v;
  } catch {}
  let surfaces: SurfaceOverrides = {};
  try {
    const raw = localStorage.getItem(SURFACES_KEY);
    if (raw) {
      const parsed: unknown = JSON.parse(raw);
      if (typeof parsed === "object" && parsed !== null) {
        surfaces = parsed as SurfaceOverrides;
      }
    }
  } catch {}
  return { mode, surfaces };
}

let clientState: GlassStoreState | null = null;
const listeners = new Set<() => void>();

function getState(): GlassStoreState {
  if (clientState === null) clientState = readInitialState();
  return clientState;
}

function setState(next: Partial<GlassStoreState>) {
  const merged = { ...getState(), ...next };
  clientState = merged;
  try {
    localStorage.setItem(MODE_KEY, merged.mode);
    localStorage.setItem(SURFACES_KEY, JSON.stringify(merged.surfaces));
  } catch {}
  for (const listener of listeners) listener();
}

function subscribe(listener: () => void): () => void {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

/* --------------------------------------------------------- media queries */

function subscribePrefersLight(onChange: () => void): () => void {
  const media = window.matchMedia("(prefers-color-scheme: light)");
  media.addEventListener("change", onChange);
  return () => media.removeEventListener("change", onChange);
}

function prefersLight(): boolean {
  return window.matchMedia("(prefers-color-scheme: light)").matches;
}

/* --------------------------------------------------------------- context */

interface GlassThemeContextValue {
  mode: GlassModeSetting;
  resolvedMode: GlassMode;
  setMode: (mode: GlassModeSetting) => void;
  surfaces: SurfaceOverrides;
  surfaceFor: (kind: GlassKind) => GlassSurface | undefined;
  setSurface: (kind: GlassKind, surface: GlassSurface | null) => void;
  resetSurfaces: () => void;
}

const GlassThemeContext = createContext<GlassThemeContextValue | null>(null);

export function GlassThemeProvider({ children }: { children: ReactNode }) {
  const mode = useSyncExternalStore(
    subscribe,
    () => getState().mode,
    () => serverState.mode,
  );
  const surfaces = useSyncExternalStore(
    subscribe,
    () => getState().surfaces,
    () => serverState.surfaces,
  );
  const systemLight = useSyncExternalStore(
    subscribePrefersLight,
    prefersLight,
    () => false,
  );

  const resolvedMode: GlassMode =
    mode === "system" ? (systemLight ? "light" : "dark") : mode;

  // Sync the external system (documentElement) — no React state writes here.
  useEffect(() => {
    const dark = resolvedMode === "dark";
    document.documentElement.classList.toggle("dark", dark);
    document.documentElement.style.colorScheme = dark ? "dark" : "light";
  }, [resolvedMode]);

  const value = useMemo<GlassThemeContextValue>(
    () => ({
      mode,
      resolvedMode,
      setMode: (m) => setState({ mode: m }),
      surfaces,
      surfaceFor: (kind) => surfaces[kind],
      setSurface: (kind, surface) =>
        setState({
          surfaces: (() => {
            const next = { ...surfaces };
            if (surface === null) delete next[kind];
            else next[kind] = surface;
            return next;
          })(),
        }),
      resetSurfaces: () => setState({ surfaces: {} }),
    }),
    [mode, resolvedMode, surfaces],
  );

  return (
    <GlassThemeContext.Provider value={value}>
      {children}
    </GlassThemeContext.Provider>
  );
}

export function useGlassTheme(): GlassThemeContextValue {
  const ctx = useContext(GlassThemeContext);
  if (!ctx) {
    throw new Error("useGlassTheme must be used inside <GlassThemeProvider>.");
  }
  return ctx;
}

"use client";

import * as React from "react";
import { useAtlasMember } from "@/components/glass-atlas";
import { LiquidGlass } from "@/components/liquid-glass";
import {
  resolveGlassStyle,
  type GlassKind,
  type GlassMode,
  type GlassSurface,
} from "@/lib/glass-theme";
import { useGlassTheme } from "@/components/glass/glass-theme-provider";
import { cn } from "@/lib/utils";
import { useAdaptiveContrast } from "@/components/adaptive-contrast";
import { sampleFromLuminance } from "@/lib/contrast";
import { useGlassScene, useGlassSettings } from "@/components/glass-scene";

const GlassSurfaceContext = React.createContext<{ lightInk: boolean } | null>(null);
export function useWithinGlassSurface() {
  return Boolean(React.useContext(GlassSurfaceContext));
}
/** Foreground context for custom low-level LiquidGlass compositions. Adds no DOM or optics. */
export function GlassContent({ink, children}: {ink: "light" | "dark"; children: React.ReactNode}) {
  return <GlassSurfaceContext.Provider value={{lightInk: ink === "light"}}>{children}</GlassSurfaceContext.Provider>;
}

export interface GlassSurfaceProps
  extends Omit<React.HTMLAttributes<HTMLElement>, "children"> {
  kind?: GlassKind;
  /** Automatic background sampling, or an explicit text color. */
  ink?: "auto" | "light" | "dark";
  /** Add only the neutral overlay needed by the sampled background. */
  contrastProtection?: boolean;
  /** Compose onto one shadcn/Radix component that forwards props and ref. */
  asChild?: boolean;
  surface?: GlassSurface;
  mode?: GlassMode;
  radius?: number;
  shape?: import("@/lib/glass").GlassShape;
  /** Classify a bounded scene on paints; explicit local blur remains authoritative. */
  adaptiveBackdrop?: boolean;
  config?: Partial<import("@/lib/glass").LensParams>;
  deformation?: {x: number; y: number};
  sceneRef?: React.RefObject<HTMLElement | null>;
  frameRate?: number;
  /** Share optics or admit this surface to the document budget. */
  rendering?: "auto" | "shared";
  /** Disable atlas batching when the surface needs its own transform. */
  composite?: boolean;
  /** Higher values are admitted first; overlays use 10. The device cap still applies. */
  priority?: number;
  tintBlendMode?: React.CSSProperties["mixBlendMode"];
  as?: "div" | "section" | "aside" | "nav" | "header" | "footer" | "article";
  /** @deprecated Surfaces use optical edges without elevation. */
  shadow?: boolean;
  children?: React.ReactNode;
  ref?: React.Ref<HTMLElement>;
}

/**
 * The one component every glass UI part is built on. Resolves the material
 * for a component family (kind), honoring explicit overrides, the global
 * per-kind override map and the active light/dark mode.
 *
 * Children render directly into the glass root — layout classes (flex,
 * grid, p-*, gap-*) behave exactly like they would on a plain div.
 */
export function GlassSurface({
  kind = "card",
  ink: requestedInk,
  contrastProtection: requestedProtection,
  asChild = false,
  sceneRef,
  rendering = "auto",
  composite = true,
  priority,
  tintBlendMode,
  surface,
  mode,
  radius,
  shape: requestedShape,
  adaptiveBackdrop = true,
  config,
  deformation,
  as,
  shadow = false,
  className = "",
  children,
  ref,
  style: rootStyle,
  ...rest
}: GlassSurfaceProps) {
  const inheritedSurface = React.useContext(GlassSurfaceContext);
  // React context crosses portals; an overlay still needs its own optical layer.
  const overlay = /dialog|popover|tooltip|select|drawer|sheet|command|dropdown|context-menu|hover-card|toast/.test(kind);
  const parentSurface = overlay ? null : inheritedSurface;
  const theme = useGlassTheme();
  const scene = useGlassScene();
  const settings = useGlassSettings();
  const ink = requestedInk ?? settings.ink ?? "auto";
  const contrastProtection =
    requestedProtection ?? settings.contrastProtection ?? true;
  const effectiveMode = mode ?? scene?.appearance ?? theme.resolvedMode;
  const effectiveSurface = surface ?? settings.surface ?? theme.surfaceFor(kind);
  const style = resolveGlassStyle({
    kind,
    surface: effectiveSurface,
    mode: effectiveMode,
    config: { ...settings.config, ...scene?.config, ...config },
    radius: radius ?? settings.radius,
  });
  const shape=requestedShape ?? (style.radius>=999 ? "round" : "squircle");
  // A higher layer softens the text and controls it captures underneath it.
  // A local override remains useful for deliberately clear overlays.
  if (overlay && config?.blur === undefined) {
    style.params.blur = Math.max(style.params.blur, kind === "tooltip" ? 4 : /dialog|drawer|sheet|command/.test(kind) ? 8 : 6);
  }
  const blend =
    tintBlendMode ?? (effectiveMode === "light" ? "normal" : "multiply");
  const localRef = React.useRef<HTMLElement | null>(null);
  const setRef = React.useCallback(
    (node: HTMLElement | null) => {
      localRef.current = node;
      if (typeof ref === "function") return ref(node);
      if (ref) ref.current = node;
    },
    [ref],
  );
  const compatibleConfig = !config || Object.keys(config).every(key => key === "tint" || key === "tintColor");
  const atlas = useAtlasMember(localRef, style.radius, composite && !parentSurface && !overlay && rendering === "auto" && compatibleConfig && !deformation && !sceneRef && (effectiveSurface === undefined || effectiveSurface === "clear"), shape);
  const sample = useAdaptiveContrast(localRef, {
    enabled: (ink === "auto" || settings.themeBehavior === "duotheme") && !parentSurface,
    tone: settings.themeBehavior === "duotheme" && ink !== "auto" ? ink : undefined,
    source: sceneRef ?? scene?.source,
    live: scene?.live ?? false,
    interval: 300,
    tintColor: style.params.tintColor,
    tintOpacity: style.params.tint,
    tintBlendMode: blend,
    brightness: style.params.brightness,
    saturate: style.params.saturate,
    contrast: style.params.contrast,
    fallback: sampleFromLuminance(effectiveMode === "dark" ? 0.02 : 0.9, 0),
  });
  const tone = ink === "auto" ? (parentSurface?.lightInk ?? sample.tone === "light") : ink === "light";
  const foreground = tone ? "#ffffff" : "#000000";
  const background = tone ? "#151719" : "#ffffff";
  const colors = {
    "--glass-action": "#006de5",
    "--background": background,
    "--foreground": foreground,
    "--card": "transparent",
    "--card-foreground": foreground,
    "--muted": tone ? "#ffffff18" : "#0000000a",
    "--muted-foreground": foreground,
    "--popover": background,
    "--popover-foreground": foreground,
    "--primary": foreground,
    "--primary-foreground": background,
    "--secondary": tone ? "#ffffff18" : "#0000000a",
    "--secondary-foreground": foreground,
    "--accent": tone ? "#ffffff20" : "#0000000e",
    "--accent-foreground": foreground,
    "--input": tone ? "#ffffff45" : "#00000030",
    "--border": tone ? "#ffffff30" : "#00000020",
    "--ring": foreground,
    "--destructive": tone ? "#ffb4b4" : "#a10820",
    "--sidebar": "transparent",
    "--sidebar-foreground": foreground,
    "--sidebar-primary": foreground,
    "--sidebar-primary-foreground": background,
    "--sidebar-accent": tone ? "#ffffff20" : "#0000000e",
    "--sidebar-accent-foreground": foreground,
    "--sidebar-border": tone ? "#ffffff30" : "#00000020",
    "--sidebar-ring": foreground,
    colorScheme: tone ? "dark" : "light",
  };
  const protection =
    (ink === "auto" || settings.themeBehavior === "duotheme") && contrastProtection && !parentSurface
      ? sample.samples || sample.inherited
        ? (sample.scrimOpacity ?? 0)
        : 0.12
      : 0;

  return (
    <GlassSurfaceContext.Provider value={{ lightInk: tone }}>
      <LiquidGlass
        preset={effectiveSurface ?? "clear"}
        config={style.params}
        deformation={deformation}
        radius={style.radius}
        shape={shape}
        adaptiveBackdrop={adaptiveBackdrop}
        preserveBlur={overlay || config?.blur !== undefined || settings.config?.blur !== undefined || scene?.config?.blur !== undefined || effectiveSurface !== "clear"}
        tintBlendMode={blend}
        as={as}
        asChild={asChild}
        sceneRef={sceneRef}
        ref={setRef}
        readability={{
          color: tone ? "#000000" : "#ffffff",
          opacity: protection,
        }}
        rendering={atlas ? "composited" : parentSurface ? "inherited" : rendering}
        compositorReady={atlas?.active}
        priority={priority ?? (overlay ? 10 : 0)}
        data-adaptive-tone={tone ? "light" : "dark"}
        data-adaptive-source={
          sample.inherited
            ? "inherited"
            : sample.samples
              ? "sampled"
              : "fallback"
        }
        data-glass-compositor={atlas ? "atlas" : undefined}
        data-glass-await-optics={overlay && Boolean(scene) ? "true" : undefined}
        data-glass-appearance={effectiveMode}
        data-glass-theme-behavior={settings.themeBehavior ?? "unitheme"}
        data-glass-shape={shape}
        data-glass={kind}
        data-glass-surface={effectiveSurface ?? "default"}
        data-glass-mode={tone ? "dark" : "light"}
        style={{ ...colors, ...rootStyle } as React.CSSProperties}
        className={cn(
          "text-foreground",
          !parentSurface && "glass-material",
          shadow && "shadow-none",
          className,
        )}
        {...rest}
      >
        {children}
      </LiquidGlass>
    </GlassSurfaceContext.Provider>
  );
}

"use client";

import * as React from "react";
import { MonitorIcon, MoonIcon, SunIcon } from "lucide-react";
import { cn } from "@/lib/utils";
import {
  GLASS_KINDS,
  GLASS_SURFACES,
  SURFACE_LABELS,
  type GlassKind,
  type GlassSurface,
} from "@/lib/glass-theme";
import {
  useGlassTheme,
  type GlassModeSetting,
} from "@/components/glass/glass-theme-provider";

const MODE_OPTIONS: {
  value: GlassModeSetting;
  label: string;
  icon: React.ReactNode;
}[] = [
  { value: "light", label: "Light", icon: <SunIcon className="size-3.5" /> },
  { value: "dark", label: "Dark", icon: <MoonIcon className="size-3.5" /> },
  {
    value: "system",
    label: "System",
    icon: <MonitorIcon className="size-3.5" />,
  },
];

/**
 * Keyboard behaviour for a `role="radiogroup"`.
 *
 * ARIA requires a radio group to be a single tab stop whose arrow keys move
 * between radios — and, for a single-select group, moving focus also selects.
 * Without this every radio sits in the tab order and arrow keys do nothing, so
 * the control is unusable by keyboard.
 */
function useRadioGroupKeyboard(
  count: number,
  onSelect: (index: number) => void,
) {
  const [focused, setFocused] = React.useState(0);
  const refs = React.useRef<(HTMLButtonElement | null)[]>([]);

  const goTo = React.useCallback(
    (index: number) => {
      const next = ((index % count) + count) % count;
      setFocused(next);
      onSelect(next);
      refs.current[next]?.focus();
    },
    [count, onSelect],
  );

  const onKeyDown = React.useCallback(
    (event: React.KeyboardEvent<HTMLDivElement>) => {
      const deltas: Record<string, number> = {
        ArrowRight: 1,
        ArrowDown: 1,
        ArrowLeft: -1,
        ArrowUp: -1,
      };
      const delta = deltas[event.key];
      if (delta !== undefined) {
        event.preventDefault();
        goTo(focused + delta);
      } else if (event.key === "Home") {
        event.preventDefault();
        goTo(0);
      } else if (event.key === "End") {
        event.preventDefault();
        goTo(count - 1);
      }
    },
    [count, focused, goTo],
  );

  // Only the focused radio is reachable by Tab.
  const tabIndexFor = (index: number) => (index === focused ? 0 : -1);

  return { focused, setFocused, refs, onKeyDown, tabIndexFor };
}

export function GlassModeToggle({ className }: { className?: string }) {
  const { mode, setMode } = useGlassTheme();
  const select = React.useCallback(
    (index: number) => {
      const opt = MODE_OPTIONS[index];
      if (opt) setMode(opt.value);
    },
    [setMode],
  );
  const { setFocused, refs, onKeyDown, tabIndexFor } = useRadioGroupKeyboard(
    MODE_OPTIONS.length,
    select,
  );

  return (
    <div
      role="radiogroup"
      aria-label="Glass theme"
      onKeyDown={onKeyDown}
      className={cn(
        "glass-chip flex items-center gap-0.5 rounded-full p-0.5",
        className,
      )}
    >
      {MODE_OPTIONS.map((opt, index) => (
        <button
          key={opt.value}
          ref={(el) => {
            refs.current[index] = el;
          }}
          type="button"
          role="radio"
          aria-checked={mode === opt.value}
          // The label is hidden below `sm`, so the icon alone must not be the
          // accessible name.
          aria-label={opt.label}
          data-testid={`mode-${opt.value}`}
          tabIndex={tabIndexFor(index)}
          onFocus={() => setFocused(index)}
          onClick={() => setMode(opt.value)}
          className={cn(
            "flex cursor-pointer items-center gap-1.5 rounded-full px-2.5 py-1 text-[11px] font-semibold transition-colors",
            "focus-visible:ring-2 focus-visible:ring-ring/50 focus-visible:outline-none",
            mode === opt.value
              ? "bg-foreground text-background"
              : "text-muted-foreground hover:text-foreground",
          )}
        >
          {opt.icon}
          <span className="hidden sm:inline">{opt.label}</span>
        </button>
      ))}
    </div>
  );
}

export function SurfacePicker({
  kind,
  value,
  onValue,
  allowAuto = true,
  testIdPrefix,
  className,
}: {
  kind?: GlassKind;
  value?: GlassSurface | undefined;
  onValue: (surface: GlassSurface | null) => void;
  allowAuto?: boolean;
  testIdPrefix?: string;
  className?: string;
}) {
  const showAuto = allowAuto && !kind;
  const options = React.useMemo<(GlassSurface | null)[]>(
    () => [...(showAuto ? [null] : []), ...GLASS_SURFACES],
    [showAuto],
  );
  const select = React.useCallback(
    (index: number) => {
      const next = options[index];
      if (next !== undefined) onValue(next);
    },
    [onValue, options],
  );
  const { setFocused, refs, onKeyDown, tabIndexFor } = useRadioGroupKeyboard(
    options.length,
    select,
  );
  const label = (surface: GlassSurface | null) =>
    surface === null ? "Auto" : SURFACE_LABELS[surface];

  return (
    <div
      role="radiogroup"
      aria-label={kind ? `Surface for ${kind}` : "Global glass surface"}
      onKeyDown={onKeyDown}
      className={cn(
        "glass-chip flex flex-wrap items-center gap-0.5 rounded-full p-0.5",
        className,
      )}
    >
      {options.map((s, index) => {
        const isSelected = s === (value ?? null);
        return (
          <button
            key={s ?? "auto"}
            ref={(el) => {
              refs.current[index] = el;
            }}
            type="button"
            role="radio"
            aria-checked={isSelected}
            aria-label={label(s)}
            data-testid={`${testIdPrefix ?? "surface"}-${s ?? "auto"}`}
            tabIndex={tabIndexFor(index)}
            onFocus={() => setFocused(index)}
            onClick={() => onValue(s)}
            className={cn(
              "cursor-pointer rounded-full px-2.5 py-1 text-[11px] font-semibold transition-colors",
              "focus-visible:ring-2 focus-visible:ring-ring/50 focus-visible:outline-none",
              isSelected
                ? "bg-foreground text-background"
                : "text-muted-foreground hover:text-foreground",
            )}
          >
            {label(s)}
          </button>
        );
      })}
    </div>
  );
}

/** Global picker that re-pours every component family at once. */
export function GlobalSurfacePicker() {
  const { surfaces, setSurface, resetSurfaces } = useGlassTheme();
  const allSame = (() => {
    const values = Object.values(surfaces).filter(Boolean) as GlassSurface[];
    if (values.length === 0) return undefined;
    return values.every((v) => v === values[0])
      ? values[0]
      : ("mixed" as const);
  })();

  return (
    <div className="flex flex-wrap items-center gap-2">
      <SurfacePicker
        value={
          typeof allSame === "string" && allSame !== "mixed"
            ? allSame
            : undefined
        }
        onValue={(s) => {
          if (s === null) resetSurfaces();
          else for (const k of GLASS_KINDS) setSurface(k, s);
        }}
        testIdPrefix="global-surface"
      />
    </div>
  );
}

