import {
  GlassSurface,
  type GlassSurfaceProps,
} from "@/components/glass/glass-surface";
import {
  Card,
  CardHeader,
  CardTitle,
  CardDescription,
  CardContent,
  CardFooter,
} from "@/components/ui/card";
import { GlassButton as Button } from "@/components/glass/glass-button";
