export function GlassToggle({
  className,
  variant = "default",
  size = "default",
  asChild,
  children,
  ...props
}: React.ComponentProps<typeof Toggle>) {
  const within = useWithinGlassSurface();
  const classes = cn(
    toggleVariants({ variant, size }),
    "h-10 rounded-[12px] px-4 hover:bg-foreground/4 data-[state=on]:bg-foreground/9 aria-pressed:bg-foreground/9",
    within ? "border-0 bg-transparent shadow-none" : "glass-chip",
    className,
  );
  if (!within)
    return (
      <Toggle
        variant={variant}
        size={size}
        {...props}
        asChild
        className={classes}
      >
        <GlassSurface asChild shadow={false}>
          {asChild ? children : <button type="button">{children}</button>}
        </GlassSurface>
      </Toggle>
    );
  return (
    <Toggle
      variant={variant}
      size={size}
      {...props}
      asChild={asChild}
      className={classes}
    >
      {children}
    </Toggle>
  );
}

export function GlassToggleGroup({
